import{_ as e,o as r,c as o,ag as i}from"./chunks/framework.DNmTgtHf.js";const h=JSON.parse('{"title":"Part 30 — Interview & Career Prep","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_30_Interview_Career_Prep.md","filePath":"todo/study_plan/parts/Part_30_Interview_Career_Prep.md"}'),a={name:"todo/study_plan/parts/Part_30_Interview_Career_Prep.md"};function d(n,t,s,c,l,m){return r(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="part-30-—-interview-career-prep" tabindex="-1">Part 30 — Interview &amp; Career Prep <a class="header-anchor" href="#part-30-—-interview-career-prep" aria-label="Permalink to &quot;Part 30 — Interview &amp; Career Prep&quot;">​</a></h1><blockquote><p>For SDE2 → SDE3 / Staff and for external moves. This Part is meta — it&#39;s about packaging everything from Parts 1–29 and 31 into a story interviewers want to buy.</p></blockquote><blockquote><p><strong>Sprint allocation:</strong> Light touch + intensifies Week 12 (mock-loop week). <strong>Budget: ~1-2 hrs ongoing, peaks Week 12 (~10 hrs mock loop).</strong></p></blockquote><h2 id="_30-interview-career-prep-—-topic-inventory" tabindex="-1">30 Interview &amp; Career Prep — topic inventory <a class="header-anchor" href="#_30-interview-career-prep-—-topic-inventory" aria-label="Permalink to &quot;30 Interview &amp; Career Prep — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>Coding round — brute force → optimize → code → test → edge cases</td><td>🔴 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>2</td><td>Machine coding / LLD — clarify → classes → interfaces → sequence → edge cases (45–90 min)</td><td>🔴 🎯</td><td>D</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: 60-min LLD timed mock — pick a problem from <code>reference/PracticeProblems.md</code>, run the full clarify→classes→interfaces sequence end-to-end (60 min)</td></tr><tr><td>3</td><td>System design / HLD — requirements → estimates → API → HLD → deep-dive → tradeoffs</td><td>🔴 🎯</td><td>D</td><td>3 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: 45-min HLD timed mock — pick a problem from <code>reference/PracticeProblems.md</code>, sketch requirements→estimates→API→HLD on paper (45 min)</td></tr><tr><td>4</td><td>Behavioral / leadership — STAR method, prepared stories (have 5–8 ready)</td><td>🔴 🎯</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: write down 3 STAR stories from your last year (situation → task → action → result + explicit impact) (45 min)</td></tr><tr><td>5</td><td>SDE2 vs SDE3 vs Staff vs Principal — scope of impact, ambiguity tolerance, influence radius</td><td>🔴 🎯</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>6</td><td>Promotion criteria at your company — write them down, gap-analyze quarterly</td><td>🔴 🎯</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>7</td><td>Bar-raiser / cross-functional rounds</td><td>🟠 🎯</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>8</td><td>Hiring manager — motivation, growth, fit</td><td>🟠 🎯</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>9</td><td>Brag doc / weekly notes habit — promotion currency</td><td>🟠 🎯</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>(Cross-ref Part 24 brag doc)</td></tr><tr><td>10</td><td>Peer feedback — solicit early, give precisely</td><td>🟠 🎯</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>11</td><td>Visibility compounders — design docs, tech talks, mentoring</td><td>🟠 🎯</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>12</td><td>levels.fyi, Glassdoor, Blind — compensation benchmarks</td><td>🟠 🎯</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>13</td><td>Negotiation basics — competing offers, signing bonus, RSU cliffs and vesting</td><td>🟠 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>14</td><td>Reference management</td><td>🟠 🎯</td><td>M</td><td>30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>15</td><td>External presence — blog, GitHub, OSS contributions</td><td>🟡</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>16</td><td>Speaking at conferences / meetups</td><td>🟡</td><td>M</td><td>30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~11 hrs</td><td>~1 wk</td><td></td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~17.75 hrs</td><td>~1.6 wk</td><td></td></tr><tr><td>Full Part (all items including 🟡)</td><td>~19 hrs</td><td>~1.75 wk</td><td></td></tr></tbody></table><blockquote><p>The real learning here is in <em>practice</em>, not study hours. Mock interviews + actual interviews compound faster than reading. Treat this Part as a forcing function: use mocks to discover gaps in Parts 1–29, then go deepen there.</p></blockquote><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> Walk me through how you&#39;d approach a system design round. <ul><li><strong>Why asked:</strong> Most senior signal in a single round. Sequence: (1) Clarify requirements (functional + non-functional, scale, SLAs) — 5 min. (2) Estimate: QPS, storage, bandwidth — 3 min. (3) API design — 5 min. (4) High-level architecture (data flow, components) — 10 min. (5) Deep-dive on 1-2 components the interviewer picks — 15 min. (6) Tradeoffs + alternatives — 5 min. Don&#39;t jump to architecture before requirements are pinned.</li></ul></li><li><strong>Q:</strong> STAR method — give me an example from your work. <ul><li><strong>Why asked:</strong> Behavioral round signal. STAR = Situation (context), Task (your responsibility), Action (what you did, specifically), Result (outcome + measurable impact). Bad: &quot;I improved performance.&quot; Good: &quot;Service P99 was 2.5s breaching the 1s SLA; I was tech lead; I profiled with async-profiler, found a JDBC connection pool starvation under spike load, fixed the pool sizing + added circuit breaker, P99 dropped to 600ms, no SLA breach for 6 months.&quot;</li></ul></li><li><strong>Q:</strong> SDE3 vs Staff — what&#39;s the scope shift? <ul><li><strong>Why asked:</strong> Promotion-context calibration. SDE3: owns features end-to-end, mentors 1-2 juniors, contributes to design decisions. Staff: owns <em>systems</em> (multiple features / multiple teams), influences cross-team architecture, mentors seniors, drives org-wide tech strategy. The shift is from &quot;I can build hard things&quot; to &quot;I make hard things possible for others.&quot;</li></ul></li><li><strong>Q:</strong> How would you negotiate a competing offer? <ul><li><strong>Why asked:</strong> Practical career skill. (1) Don&#39;t reveal numbers first if you can avoid it. (2) Have a real competing offer (or strong BATNA) — bluffing is detectable. (3) Negotiate the full package: base, signing, RSU, vesting cliff, equity refresh. (4) Use cliff and vesting curve as levers (4-year cliff is normal; 1-year cliff is normal at start). (5) Ask for the offer in writing; let the recruiter run internal escalation.</li></ul></li><li><strong>Q:</strong> How do you prepare for a coding round? <ul><li><strong>Why asked:</strong> Practical. Patterns over puzzles: hash maps for &quot;find pair&quot;, two pointers for sorted arrays, BFS/DFS for graphs, DP for &quot;count ways&quot;/&quot;min/max&quot;. Practice talking through brute force first; explicitly call out optimization moves. Test with small + edge + empty inputs. 30 min of warm-up per day for 2-3 weeks before a target interview beats cramming 3 hrs the day before.</li></ul></li><li><strong>Q:</strong> Bar-raiser round — what are they evaluating? <ul><li><strong>Why asked:</strong> Amazon-canonical, increasingly common elsewhere. Bar-raiser doesn&#39;t work in the team — their job is to enforce the hiring bar regardless of team pressure. They evaluate: leadership principles (or equivalent), depth of judgment, ability to disagree-and-commit, growth trajectory. Less about technical skill, more about decision-making and ownership patterns.</li></ul></li><li><strong>Q:</strong> External presence — does it matter? <ul><li><strong>Why asked:</strong> Career-strategy question. Matters most at: hiring (visibility shortens funnel), promotion to Staff+ (external rep is part of the case), founder-level moves. Matters least at: SDE2 → SDE3 (internal impact dominates). Lowest-effort high-leverage: thoughtful blog every 2 months, GitHub with real projects, LinkedIn presence with substantive posts.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> You give a great technical answer. Interviewer says &quot;okay but why this and not X?&quot; You say &quot;I haven&#39;t really thought about X.&quot; What&#39;s the missing signal? <ul><li><strong>Gotcha:</strong> Senior interviews test <em>tradeoff awareness</em>. Knowing the answer isn&#39;t enough — you must know what you <em>didn&#39;t</em> choose and why. Even one sentence per alternative (&quot;X would work but adds operational complexity for marginal benefit&quot;) is enough. Lack of comparison is a junior tell.</li></ul></li><li><strong>Q:</strong> You answer behavioral with &quot;we&quot; instead of &quot;I.&quot; Why is this bad? <ul><li><strong>Gotcha:</strong> Behavioral rounds evaluate <em>your</em> impact, not the team&#39;s. &quot;We optimized the cache&quot; → &quot;I led the cache optimization; my role was X.&quot; Don&#39;t claim sole credit if untrue, but don&#39;t bury your contribution. Most candidates underclaim from politeness; the interviewer can&#39;t tell what <em>you</em> did.</li></ul></li><li><strong>Q:</strong> You&#39;re asked to design a payment system. You start drawing immediately. What did you skip? <ul><li><strong>Gotcha:</strong> Requirements gathering. &quot;How many payments per second? What&#39;s the consistency requirement? Cross-border or domestic? What&#39;s the SLA?&quot; — these change the design fundamentally. Jumping to architecture without scope = junior signal. Even with experience, force yourself to ask 3-5 clarifying questions before drawing.</li></ul></li><li><strong>Q:</strong> You accept the first offer because you don&#39;t want to seem greedy. Six months later, you find a peer made 30% more. Lesson? <ul><li><strong>Gotcha:</strong> Negotiation isn&#39;t greed. Companies <em>expect</em> negotiation; they make first offers below their max precisely because they assume candidates will counter. Not negotiating signals you don&#39;t value yourself. Polite, specific counters (&quot;based on competing offers / market data, I was hoping for X&quot;) are normal and respected.</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>HLD interview practice — 5 full mocks</strong> (~10 hrs) — pick 5 problems from <code>reference/PracticeProblems.md</code>, do timed 45-min mocks, record yourself, review for gaps. Mocks expose what reading doesn&#39;t.</li><li><strong>LLD interview practice — 5 full mocks</strong> (~10 hrs) — same pattern, focus on class design + sequence diagrams + edge cases.</li><li><strong>STAR story bank — 8 stories</strong> (~4 hrs) — write 8 behavioral stories covering: technical leadership, conflict resolution, mentoring, failure + recovery, cross-team influence, ambiguous-scope decision, on-call incident, scope cut. Refine over time.</li><li><strong>Promotion plan to Staff</strong> (~ongoing) — write down your company&#39;s Staff criteria. Quarterly gap analysis. Tie each gap to a specific upcoming project. This compounds.</li></ul><h2 id="hands-on-exercises-practice-advanced" tabindex="-1">Hands-on exercises (Practice + Advanced) <a class="header-anchor" href="#hands-on-exercises-practice-advanced" aria-label="Permalink to &quot;Hands-on exercises (Practice + Advanced)&quot;">​</a></h2><p>Warm-up interview exercises are listed inline in the topic-table Resources column (counted in main Time summary). Longer exercises below are tracked separately.</p><h3 id="practice-—-mid-level-60-90-min-each" tabindex="-1">Practice — mid-level (~60-90 min each) <a class="header-anchor" href="#practice-—-mid-level-60-90-min-each" aria-label="Permalink to &quot;Practice — mid-level (~60-90 min each)&quot;">​</a></h3><ol><li><strong>LLD mock — Parking Lot or LRU Cache</strong> (~75 min) — pick from <code>reference/PracticeProblems.md</code>. Timed: 15 min requirements, 30 min design, 20 min code skeleton, 10 min edge cases. Record yourself. Review for clarity + completeness.</li><li><strong>HLD mock — TinyURL or Rate Limiter</strong> (~60 min) — pick from <code>reference/PracticeProblems.md</code>. Timed: 5 min requirements, 3 min estimates, 5 min API, 30 min HLD + deep-dive, 10 min tradeoffs. Record yourself.</li><li><strong>STAR story drafting session</strong> (~60 min) — pick 3 work events from the last 12 months. Write each as STAR with explicit impact. Practice telling each in under 2 min out loud.</li></ol><h3 id="advanced-—-senior-grade-depth-90-min-each" tabindex="-1">Advanced — senior-grade depth (~90+ min each) <a class="header-anchor" href="#advanced-—-senior-grade-depth-90-min-each" aria-label="Permalink to &quot;Advanced — senior-grade depth (~90+ min each)&quot;">​</a></h3><ol start="4"><li><strong>Full mock interview loop simulation</strong> (~3 hrs) — back-to-back: 1 coding round (45 min), 1 LLD (60 min), 1 HLD (60 min), 1 behavioral (45 min). Same day. This is the realistic fatigue test.</li><li><strong>Peer mock interview</strong> (~90 min) — find a peer at similar level. They interview you, you interview them. Honest feedback after each. More signal than self-mocking.</li></ol><h3 id="hands-on-time-summary-practice-advanced-only" tabindex="-1">Hands-on time summary (Practice + Advanced only) <a class="header-anchor" href="#hands-on-time-summary-practice-advanced-only" aria-label="Permalink to &quot;Hands-on time summary (Practice + Advanced only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Total time</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>Practice (mid-level)</td><td>~3.25 hrs</td><td>~0.3 wk</td><td></td></tr><tr><td>Advanced (senior-grade)</td><td>~4.5 hrs</td><td>~0.4 wk</td><td></td></tr><tr><td><strong>Combined hands-on (Practice + Advanced)</strong></td><td><strong>~7.75 hrs</strong></td><td><strong>~0.7 wk</strong></td><td></td></tr></tbody></table><blockquote><p>Warm-up exercises (counted in main Time summary above) total ~2.5 hrs for Part 30 across 3 in-table warm-ups.</p></blockquote><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. System design round sequence?</strong> A. Requirements → estimates → API → HLD → deep-dive → tradeoffs. Don&#39;t jump to architecture before scope is pinned. Always cover what you <em>didn&#39;t</em> choose.</p><p><strong>Q. STAR method?</strong> A. Situation, Task, Action, Result. Plus explicit impact (number, %, time saved). &quot;I&quot; not &quot;we&quot; — your contribution must be clear.</p><p><strong>Q. SDE3 vs Staff scope shift?</strong> A. SDE3 owns features; Staff owns systems across teams. Shift from &quot;I can build hard things&quot; to &quot;I make hard things possible for others.&quot;</p><p><strong>Q. Negotiation — what to negotiate beyond base?</strong> A. Signing bonus, RSU grant, vesting curve, cliff, equity refresh, start date, level. Full package matters more than base alone.</p><p><strong>Q. Coding round — sequence?</strong> A. Brute force first (always) → identify bottleneck → optimize → code → test (small, edge, empty) → discuss complexity. Talk while you think.</p><p><strong>Q. Brag doc — why and what shape?</strong> A. Live document, append weekly. STAR-shaped entries with impact statements. Six months in, your promotion case writes itself. Currency for both internal promotion and external moves.</p>',30)])])}const g=e(a,[["render",d]]);export{h as __pageData,g as default};
